from collections import Counter
from typing import TypeAlias
Transcript: TypeAlias = tuple[int, int, int]

def image(a: int, x: int, q: int) -> int:
    return (a * x) % q

def real(q: int, a: int, w: int, e: int) -> Counter[Transcript]:
    return Counter((image(a, r, q), e, (r + e*w) % q) for r in range(q))

def simulated(q: int, a: int, y: int, e: int) -> Counter[Transcript]:
    return Counter(((image(a, z, q) - e*y) % q, e, z) for z in range(q))

if __name__ == "__main__":
    q, a, w = 12, 4, 5
    y = image(a, w, q)
    for e in (0, 1):
        left, right = real(q, a, w, e), simulated(q, a, y, e)
        print(e, left == right, sorted(left.items()))

from collections import Counter

def distribution(q: int, a: int, w: int, e: int) -> Counter[tuple[int, int, int]]:
    return Counter(((a*r) % q, e, (r + e*w) % q) for r in range(q))

def witnesses(q: int, a: int, y: int) -> list[int]:
    return [w for w in range(q) if (a*w) % q == y % q]

if __name__ == "__main__":
    q, a, y = 12, 4, 8
    ws = witnesses(q, a, y)
    print("witness fiber:", ws)
    for e in (0, 1):
        ds = [distribution(q, a, w, e) for w in ws]
        print("challenge", e, "all equal:", all(d == ds[0] for d in ds))

